// Compound Assignment Operators Overview

int value = 10;
unsigned char status_flags = 0b0001;

// Arithmetic
value += 5;     // value = value + 5;
value *= 2;     // value = value * 2;
value /= 3;     // value = value / 3;

// Bitwise (often used for performance/masking)
status_flags |= 0b0100; // Set specific bit (OR)
status_flags &= ~0b0001; // Clear specific bit (AND)
value <<= 1;    // Efficient shift (Multiplication by 2)
status_flags ^= 0xFF;   // Toggle all bits (XOR)

// Note: Variable evaluated only once (e.g., in x[i++] += y)
